def resolve_roots(frontend_arg: str | None, backend_arg: str | None):
    cwd = Path.cwd().resolve()

    fe_candidates: list[Path] = []
    be_candidates: list[Path] = []

    if frontend_arg:
        fe_candidates.append(Path(frontend_arg).expanduser().resolve())
    if backend_arg:
        be_candidates.append(Path(backend_arg).expanduser().resolve())

    fe_candidates.extend(
        [
            cwd,
            cwd / "LambdaVisionSuper",
            cwd.parent / "LambdaVisionSuper",
        ]
    )
    be_candidates.extend(
        [
            cwd,
            cwd / "LambdaVisionSuperBackEnd",
            cwd.parent / "LambdaVisionSuperBackEnd",
        ]
    )

    frontend = next(
        (
            candidate
            for candidate in fe_candidates
            if (candidate / "src/App.tsx").exists()
            and (
                candidate
                / "src/Pages/SamplingGeometryLabPage.tsx"
            ).exists()
        ),
        None,
    )
    backend = next(
        (
            candidate
            for candidate in be_candidates
            if (candidate / "app/main.py").exists()
            and (
                candidate
                / "app/services/vision_labs/sampling_geometry"
            ).exists()
        ),
        None,
    )

    if frontend is None:
        raise RuntimeError(
            "Cannot locate LambdaVisionSuper frontend. "
            "Use --frontend /path/to/LambdaVisionSuper"
        )
    if backend is None:
        raise RuntimeError(
            "Cannot locate LambdaVisionSuperBackEnd. "
            "Use --backend /path/to/LambdaVisionSuperBackEnd"
        )

    return frontend, backend


def real_path(frontend: Path, backend: Path, virtual: str) -> Path:
    if virtual.startswith("frontend/"):
        return frontend / virtual[len("frontend/") :]
    if virtual.startswith("backend/"):
        return backend / virtual[len("backend/") :]
    raise RuntimeError(f"Unknown virtual path: {virtual}")


def state_modified(path: Path, old: str, new: str) -> str:
    if not path.exists():
        return "MISSING"
    current = path.read_text(encoding="utf-8")
    if current == new:
        return "OK"
    if current == old:
        return "UPDATE"
    return "CONFLICT"


def state_created(path: Path, desired: str) -> str:
    if not path.exists():
        return "CREATE"
    if path.read_text(encoding="utf-8") == desired:
        return "OK"
    return "CONFLICT"


