    print()

    conflicts = 0

    for virtual, payload in MODIFIED.items():
        path = real_path(frontend, backend, virtual)
        state = state_modified(path, payload["old"], payload["new"])
        print(f"  [{state:9}] {virtual}")
        if state in {"CONFLICT", "MISSING"}:
            conflicts += 1

    for virtual, desired in CREATED.items():
        path = real_path(frontend, backend, virtual)
        state = state_created(path, desired)
        print(f"  [{state:9}] {virtual}")
        if state == "CONFLICT":
            conflicts += 1

